/* One question engine for the chapter activities; every action is scoped to run + position. */
let labRun=null,labChoiceQuery='',labSelectedLesson=null,labReplayToken=0,labVoice=null,labVoiceToken=0;
function labHash(s){let h=2166136261;for(const c of String(s))h=Math.imul(h^c.codePointAt(0),16777619);return h>>>0}
function labOrder(items,seed){return items.map((item,i)=>({item,n:labHash(seed+'|'+i+'|'+(item.id||item.character||item))})).sort((a,b)=>a.n-b.n).map(x=>x.item)}
function labScopeCards(lesson=labSelectedLesson||courseFocusId()){const course=currentCourse(),index=course.lessons.indexOf(lesson);return uniqueCards().filter(c=>course.lessons.indexOf(c.lesson)<=index)}
function labZh(zh,traditional){return state.settings.script==='traditional'?(traditional||text(zh)):zh}
function labShapeAllowed(p){return state.settings.script!=='traditional'||[p.target,p.from,p.to,...p.parts||[]].filter(Boolean).every(ch=>text(ch)===ch)}
function labShapePool(kind,lesson){const allowed=new Set(labScopeCards(lesson).map(c=>c.character));return (kind==='transform'?SHAPE_TRANSFORMS:COMPONENT_CHALLENGES).filter(p=>allowed.has(p.target||p.to)&&labShapeAllowed(p))}
function labWordNodes(lesson){const known=new Set(labScopeCards(lesson).map(c=>c.character)),seen=new Set();return Object.entries(WORDS).filter(([id])=>id===lesson||currentCourse().lessons.indexOf(id)>=0&&currentCourse().lessons.indexOf(id)<=currentCourse().lessons.indexOf(lesson)).flatMap(([,words])=>words).filter(w=>!seen.has(w[0])&&seen.add(w[0])).map(([zh,py,en])=>({id:zh,zh,py,en,unlocked:[...zh].filter(ch=>/[\u3400-\u9fff]/.test(ch)).length>0&&[...zh].filter(ch=>/[\u3400-\u9fff]/.test(ch)).every(ch=>state.cards[ch]?.seen>0),parts:[...zh].filter(ch=>/[\u3400-\u9fff]/.test(ch))}))}
function labEpisode(lesson){return ADVENTURE_EPISODES.find(e=>e.lesson===lesson)}
function labHomophonePool(lesson){const pool=labScopeCards(lesson).filter(c=>characterSounds(c).length===1),groups={};for(const c of pool){const sound=characterSounds(c)[0],key=sound.base+sound.tone;(groups[key]??=[]).push(c)}return Object.values(groups).filter(g=>g.length>1).flat()}
function labDescriptor(mode,item,variant=0){return {mode,item,variant}}
function labModeAvailable(mode,lesson){if(['parts','transform'].includes(mode))return labShapePool(mode,lesson).length>0;if(mode==='homophones')return labHomophonePool(lesson).length>1;if(mode==='words')return labWordNodes(lesson).some(w=>w.unlocked);if(['story','comic','scene','dialogue'].includes(mode))return !!labEpisode(lesson);return true}
function labStart(mode='mixed',lesson=labSelectedLesson||courseFocusId(),extra={}){
 if(!Object.hasOwn(LAB_MODES,mode)||!currentCourse().lessons.includes(lesson))return false;
 checkpointCurrent();labStop();labSelectedLesson=lesson;const seed=Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9),chapterCards=uniqueCards(lesson),scope=labScopeCards(lesson),target=labOrder(chapterCards,seed),episode=labEpisode(lesson);let queue=[];
 const basic=(kind,cards=target)=>cards.map(c=>labDescriptor(kind,c.character));
 if(['mixed','boss'].includes(mode)){const count=mode==='boss'?14:8,parts=labShapePool('parts',lesson),transforms=labShapePool('transform',lesson);for(let i=0;i<count;i++){const c=target[Math.floor(i/4)%target.length],variant=i%4;if(variant===0)queue.push(labDescriptor(i%8===0?'ear':'fonts',c.character,i));else if(variant===1&&parts.length)queue.push(labDescriptor('parts',parts[i%parts.length].id));else if(variant===1&&transforms.length)queue.push(labDescriptor('transform',transforms[i%transforms.length].id));else if(variant===2)queue.push(labDescriptor('dictation',c.character));else queue.push(labDescriptor('cloze',c.character));}if(episode){queue.push(labDescriptor('story',episode.id+'#0'));if(mode==='boss')queue.push(labDescriptor('dialogue',episode.id+'#2'))}}
 else if(['story','comic','scene','dialogue'].includes(mode)&&episode)queue=episode.scenes.map((_,i)=>labDescriptor(mode,episode.id+'#'+i));
 else if(['parts','transform'].includes(mode))queue=labOrder(labShapePool(mode,lesson),seed).slice(0,8).map(p=>labDescriptor(mode,p.id));
 else if(mode==='homophones')queue=basic(mode,labOrder(labHomophonePool(lesson),seed).slice(0,8));
 else if(mode==='words')queue=labOrder(labWordNodes(lesson).filter(w=>w.unlocked),seed).slice(0,8).map(w=>labDescriptor(mode,w.zh));
 else if(mode==='deck'){const deck=labData().decks.find(d=>d.id===extra.deck),recall=extra.recall===true;if(deck&&!recall&&new Set(deck.entries.map(w=>w.en)).size<2){toast('Add two different meanings for choice practice, or use Read & type with pinyin.');return false}if(deck){const entries=deck.entries.filter(w=>!recall||labCanRecall(w.py));const due=entries.filter(w=>!labData().deckWords[deck.id+'#'+w.id]||labData().deckWords[deck.id+'#'+w.id].due<=Date.now());queue=labOrder(extra.due?due:entries,seed).slice(0,10).map(w=>labDescriptor(mode,deck.id+'#'+w.id,recall?2:0));if(!queue.length)return toast(recall&&!entries.length?'Add pinyin to use Read & type.':extra.due?'No words due. You can browse or practice the whole deck.':'No words available.')}}
 else if(mode==='comeback'){const familiarCards=scope.filter(familiar),tricky=scope.filter(c=>state.quizMisses[c.character]||state.cards[c.character]?.memoryStage===0);queue=[...basic('sound',labOrder(familiarCards,seed).slice(0,4)),...basic('duel',labOrder(tricky,seed).slice(0,2))];if(!queue.length){toast('Practice a few characters in this course first. Welcome-back sets use studied material.');return false}}
 else queue=basic(mode).slice(0,8);
 if(extra.items){const allowed=new Set(extra.items);queue=queue.filter(q=>allowed.has(q.item));if(!queue.length&&['parts','transform'].includes(mode))queue=labShapePool(mode,lesson).filter(p=>allowed.has(p.id)).slice(0,8).map(p=>labDescriptor(mode,p.id))}
 if(!queue.length){toast(mode==='words'?'Practice some of this chapter’s characters to open word trails.':mode==='homophones'?'No matching-sound pairs in this scope yet. Try a later lesson.':'No suitable exercises in this scope and script. Choose another lesson or script.');return false}
 if(extra.assisted)queue=queue.map(q=>({...q,assisted:true}));
 labRun={id:'run-'+seed,course:selectedCourseId,lesson,mode,queue:queue.slice(0,24),pos:0,right:0,helped:0,misses:[],done:false,feedback:null,usedHint:false,revealed:false,partChoices:[],started:Date.now(),savedAt:Date.now(),abilityUsed:false,credited:false,deck:extra.deck||''};labData().runs[selectedCourseId]=labRun;navigate('labplay');return true;
}
function labCurrent(){return labRun?.course===selectedCourseId&&!labRun.done?labQuestion(labRun.queue[labRun.pos],labRun):null}
function labQuestion(d,r=labRun){
 if(!d||!r)return null;const seed=r.id+'|'+d.mode+'|'+d.item+'|'+d.variant,pool=labScopeCards(r.lesson),c=pool.find(card=>card.character===d.item);
 if(['story','comic','scene','dialogue'].includes(d.mode)){const [episodeId,index]=d.item.split('#'),episode=ADVENTURE_EPISODES.find(e=>e.id===episodeId&&e.lesson===r.lesson),scene=episode?.scenes[Number(index)];if(!scene)return null;const dialogue=d.mode==='dialogue';return {kind:d.mode,skill:'comprehension',item:d.item,title:dialogue?scene.replyPrompt:scene.question,scene,episode,correct:dialogue?scene.replyAnswer:scene.answer,choices:dialogue?scene.replies.map(w=>labZh(w.zh,w.traditional)):scene.choices,answer:dialogue?labZh(scene.replies[scene.replyAnswer].zh,scene.replies[scene.replyAnswer].traditional):scene.choices[scene.answer],explanation:ADVENTURE_FEEDBACK[d.item]?.[dialogue?'replyExplanation':'explanation']||scene.en,evidence:ADVENTURE_FEEDBACK[d.item]?.evidence||''}}
 if(['parts','transform'].includes(d.mode)){const p=(d.mode==='parts'?COMPONENT_CHALLENGES:SHAPE_TRANSFORMS).find(x=>x.id===d.item);if(!p||!labShapeAllowed(p)||!pool.some(c=>c.character===(p.target||p.to)))return null;const card=pool.find(c=>c.character===(p.target||p.to))||cardByChar[p.target||p.to];if(d.mode==='parts'){const distractors=[...new Set(COMPONENT_CHALLENGES.flatMap(x=>x.parts))].filter(x=>!p.parts.includes(x));const choices=labOrder([...p.parts,...labOrder(distractors,seed).slice(0,2)],seed);return {kind:'parts',skill:'shape',item:d.item,character:p.target,title:'Build '+card.pinyin+' · '+card.meaning,parts:p.parts,choices,layout:p.layout,clue:p.clue,answer:p.target,explanation:p.explanation}}
 const choices=labChoices(card,pool,seed);return {kind:'transform',skill:'shape',item:d.item,character:p.to,title:p.prompt,from:p.from,choices:choices.map(x=>han(x)),correct:choices.findIndex(x=>x.character===p.to),answer:han(card),explanation:p.explanation}}
 if(d.mode==='words'){const w=labWordNodes(r.lesson).find(w=>w.zh===d.item);if(!w)return null;const choices=labOrder([w,...labOrder(labWordNodes(r.lesson).filter(x=>x.zh!==w.zh&&x.en!==w.en),seed).slice(0,3)],seed);return {kind:'words',skill:'words',item:w.zh,title:labZh(w.zh),pinyin:w.py,choices:choices.map(x=>x.en),correct:choices.indexOf(w),answer:w.en,explanation:w.py+' · '+w.en}}
 if(d.mode==='deck'){const [id,word]=d.item.split('#'),deck=labData().decks.find(x=>x.id===id),w=deck?.entries.find(x=>x.id===word);if(!w)return null;if(d.variant===2&&labCanRecall(w.py))return {kind:'recall',skill:'words',item:d.item,wordZh:w.zh,title:labZh(w.zh,w.traditional),pinyin:w.py,context:w.context,answer:w.py,meaning:w.en,explanation:w.en};const alternatives=labOrder(deck.entries.filter(x=>x.id!==w.id&&x.en!==w.en),seed).slice(0,3),choices=labOrder([w,...alternatives],seed);return {kind:'deck',skill:'words',item:d.item,wordZh:w.zh,title:labZh(w.zh,w.traditional),pinyin:w.py,context:w.context,choices:choices.map(x=>x.en),correct:choices.indexOf(w),answer:w.en,explanation:w.py+' · '+w.en,single:choices.length<2}}
 if(!c||!pool.some(x=>x.character===c.character))return null;
 if(d.mode==='dictation')return {kind:'writing',skill:'writing',item:c.character,character:c.character,target:han(c),title:'Write the character',meaning:c.meaning,pinyin:c.pinyin,listenFirst:true,answer:han(c),explanation:c.pinyin+' · '+c.meaning};
 let peers=pool;if(d.mode==='homophones'){const sound=characterSounds(c)[0];peers=pool.filter(x=>characterSounds(x).some(s=>s.base===sound.base&&s.tone===sound.tone))}
 const choices=labChoices(c,peers,seed,d.mode==='duel');
 if(d.mode==='cloze'||d.mode==='homophones'){const example=EXAMPLE_CONTEXT[c.word]?.sentence?.[0]||c.word,sentence=example.replace(c.character,'□');return {kind:'cloze',skill:'comprehension',item:c.character,character:c.character,title:d.mode==='homophones'?'Same reading · choose by meaning':'Complete the sentence',sentence:labZh(sentence),meaning:c.meaning,pinyin:c.pinyin,choices:choices.map(x=>han(x)),correct:choices.findIndex(x=>x.character===c.character),answer:han(c),explanation:labZh(example)+' · '+(EXAMPLE_CONTEXT[c.word]?.sentence?.[2]||c.meaning)}}
 const reading=d.mode==='fonts';if(d.mode==='ear')return {kind:'ear',skill:'listening',item:c.character,character:c.character,title:'Listen, then choose the character',choices:choices.map(x=>han(x)),correct:choices.findIndex(x=>x.character===c.character),answer:han(c),pinyin:c.pinyin,explanation:han(c)+' · '+c.pinyin+' · '+c.meaning};const out={kind:reading?'fonts':'choice',skill:'recognition',item:c.character,character:c.character,title:reading?'Read this character':c.pinyin+' · '+c.meaning,pinyin:c.pinyin,choices:reading?choices.map(x=>x.meaning):choices.map(x=>han(x)),correct:choices.findIndex(x=>x.character===c.character),answer:reading?c.meaning:han(c),explanation:han(c)+' · '+c.pinyin+' · '+c.meaning,glyph:reading?han(c):'',font:d.variant%3};return out;
}
function labChoices(c,pool,seed,similar=false){let peers=pool.filter(x=>x.character!==c.character&&x.meaning!==c.meaning&&han(x)!==han(c));const meanings=new Set();peers=peers.filter(x=>!meanings.has(x.meaning)&&meanings.add(x.meaning));if(similar){const near=new Set(CONFUSIONS.filter(g=>g.chars.includes(c.character)).flatMap(g=>[...g.chars]));peers=[...peers.filter(x=>near.has(x.character)),...labOrder(peers.filter(x=>!near.has(x.character)),seed)]}else peers=labOrder(peers,seed);return labOrder([c,...peers.slice(0,3)],seed)}
function labResume(){const raw=labData().runs[selectedCourseId],clean=labValidateRun(raw,selectedCourseId);if(!clean||clean.done)return false;labRun=clean;if(!labCurrent()){toast('That exercise is unavailable. Start a new chapter run.');return false}labData().runs[selectedCourseId]=labRun;navigate('labplay');return true}
function labCheckpoint(){if(currentView==='labwrite'&&labPaper?.timed){const now=Date.now();labPaper.elapsed=Math.min(3600000,labPaper.elapsed+now-labPaper.started);labPaper.started=now}if(labRun&&labRun.course===selectedCourseId){labRun.savedAt=Date.now();labData().runs[selectedCourseId]=labRun}save()}
function labStop(){labReplayToken++;labVoiceToken++;try{labVoice?.abort?.()}catch{}labVoice=null;labTimerStop()}
function labAnswer(index,id=labRun?.id,pos=labRun?.pos){const r=labRun,q=labCurrent();if(currentView!=='labplay'||!r||r.id!==id||r.pos!==pos||r.feedback||!q||q.kind==='writing'||q.kind==='recall'||q.kind==='parts'||!Number.isInteger(index)||!q.choices[index])return;if(q.kind==='ear'&&!r.heard)return toast('Press Play before choosing an answer.');labResolve(index===q.correct,index)}
function labPart(index,id=labRun?.id,pos=labRun?.pos){const r=labRun,q=labCurrent();if(currentView!=='labplay'||!r||r.id!==id||r.pos!==pos||r.feedback||q?.kind!=='parts'||!q.choices[index]||r.partChoices.includes(index))return;r.partChoices.push(index);if(r.partChoices.length===q.parts.length){const chosen=r.partChoices.map(i=>q.choices[i]);labResolve(chosen.every((c,i)=>c===q.parts[i]),index)}else{renderLabRun();labCheckpoint()}}
function labResolve(correct,chosen=null){
 const r=labRun,q=labCurrent();if(!r||r.feedback||r.done||!q||currentView!=='labplay')return false;if(q.kind==='writing'&&correct&&!inkPassed(r))return false;if(q.kind==='recall'&&correct&&!labRecallProofs.get(r)?.has(r.pos))return false;
 const exposed=q.character&&r.queue.slice(0,r.pos).some(d=>labQuestion(d,r)?.character===q.character),helped=r.usedHint===true||r.queue[r.pos].assisted===true||q.wordZh&&labWordRecentlySeen(q.wordZh)||r.misses.includes(q.item)||!!exposed,runtimeKey=q.kind==='writing'?q.target:q.item;let xp=labRecord(q.skill,q.item,correct,helped,{reward:true,character:q.character,creditItem:['deck','recall'].includes(q.kind)?labCanonicalWord(q.wordZh):undefined});
 if(correct){r.right++;if(helped)r.helped++}else{if(!r.misses.includes(q.item))r.misses.push(q.item);const repeats=r.queue.filter(d=>d.item===q.item&&d.mode===r.queue[r.pos].mode).length;if(repeats<2&&r.queue.length<30&&!['story','comic','scene','dialogue'].includes(q.kind))r.queue.splice(Math.min(r.queue.length,r.pos+3),0,{...r.queue[r.pos],variant:r.queue[r.pos].variant})}
 labRecordDeck(q,correct,helped);if(q.wordZh)labMarkWordSeen(q.wordZh);
 // Choice, story, and construction exercises never manufacture character mastery.
 if(q.character&&!correct)state.quizMisses[q.character]=Date.now();if(q.kind==='writing'&&q.character){state.cards[q.character]=inkScheduleWriting(state.cards[q.character],correct?(helped?'hard':'good'):'again');if(correct&&!helped)state.writing[q.character]=(state.writing[q.character]||0)+1;}
 r.feedback={correct,helped,chosen,xp,key:runtimeKey};activity('cards');const day=bxDay();day.answers++;bx.totals.answers++;if(correct){day.correct++;bx.totals.correct++;if(q.kind==='writing')bx.totals.strokes++}bxSave();bxCheckQuests();bxCheckAchievements();playStudySound(correct?'correct':'retry');if(state.companion.enabled)personalityReact(correct?'recall':'retry',r.id+'-'+r.pos);labCheckpoint();renderLabRun();return true;
}
function labNext(id=labRun?.id,pos=labRun?.pos){const r=labRun;if(currentView!=='labplay'||!r||r.id!==id||r.pos!==pos||!r.feedback)return;inkStop();r.pos++;r.feedback=null;r.usedHint=false;r.helpKind='';r.heard=false;r.revealed=false;r.partChoices=[];delete r.ink;inkProofs.delete(r);if(r.pos>=r.queue.length){r.done=true;labFinish(r)}labCheckpoint();renderLabRun()}
function labFinish(r){if(r.credited)return;r.credited=true;labData().history.push({course:r.course,lesson:r.lesson,mode:r.mode,right:r.right,total:r.queue.length,helped:r.helped,at:Date.now()});labData().history=labData().history.slice(-60);save()}
function labHelp(kind='translation'){const q=labCurrent();if(!q||labRun.feedback)return;labRun.usedHint=true;labRun.helpKind=kind;if(q.kind==='writing')return inkModel();renderLabRun();labCheckpoint()}
function labHear(){const q=labCurrent();if(currentView!=='labplay'||!q)return;if(!labRun.feedback)labRun.heard=true;const zh=q.kind==='writing'?q.target:q.scene?labZh(q.scene.zh,q.scene.zhTraditional):q.character?(q.kind==='ear'&&CONTEXT_READINGS[q.character]?courseCard(q.character).word:han(courseCard(q.character))):q.title;speak(zh);if(q.wordZh)labMarkWordSeen(q.wordZh);if(!labRun.feedback&&q.kind!=='writing'&&q.kind!=='ear')labRun.usedHint=true;labCheckpoint()}
function labHearSentence(){const q=labCurrent();if(currentView!=='labplay'||!q?.context)return;if(!labRun.feedback)labRun.usedHint=true;speak(labZh(q.context));if(q.wordZh)labMarkWordSeen(q.wordZh);labCheckpoint()}

function labHintText(q){if(q.scene)return q.scene.en;if(q.kind==='parts'){const position=q.layout==='left-right'?'left':q.layout==='top-bottom'?'top':'outside';return 'Start with '+q.parts[0]+' ('+partName(q.parts[0])+') on the '+position+'. '+(q.layout==='enclosure'?'Place the other part inside it.':'Choose the next part in reading order.')}if(q.character){const c=courseCard(q.character);return (q.pinyin||c.pinyin)+' · '+c.meaning}return q.kind==='recall'?q.pinyin+' · '+q.meaning:q.explanation}

function labKeys(e){if(currentView!=='labplay'||!labRun)return false;const key=e.key.toLowerCase(),q=labCurrent();if(!q)return false;if(labRun.feedback){if([' ','enter'].includes(key)&&e.target?.tagName!=='BUTTON'){e.preventDefault();labNext();return true}return false}if(key==='h'){e.preventDefault();labHelp();return true}if(key==='l'){e.preventDefault();labHear();return true}if(q.kind==='writing'){if(['backspace','r'].includes(key)){e.preventDefault();inkRestart();return true}if(key==='1'){e.preventDefault();labResolve(false);return true}if([' ','enter','2','3'].includes(key)&&e.target?.tagName!=='BUTTON'){e.preventDefault();return true}return false}if(/^[1-9]$/.test(key)){e.preventDefault();const index=Number(key)-1;if(q.kind==='parts')labPart(index);else labAnswer(index);return true}return false}

function labUndoPart(id,pos,reset=false){const r=labRun,q=labCurrent();if(currentView!=='labplay'||!r||r.id!==id||r.pos!==pos||r.feedback||q?.kind!=='parts')return;if(reset)r.partChoices=[];else r.partChoices.pop();renderLabRun();labCheckpoint()}
function labRetryMisses(id=labRun?.id){const old=labRun;if(!old||old.id!==id||!old.done||old.course!==selectedCourseId)return false;const missed=new Set(old.misses),seen=new Set(),queue=old.queue.filter(d=>missed.has(d.item)&&!seen.has(d.mode+'|'+d.item)&&seen.add(d.mode+'|'+d.item)).map(d=>({...d,assisted:true}));if(!queue.length)return false;labStop();labRun={...old,id:'run-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,9),queue,pos:0,right:0,helped:0,misses:[],done:false,feedback:null,usedHint:false,heard:false,revealed:false,helpKind:'',partChoices:[],started:Date.now(),savedAt:Date.now(),abilityUsed:false,credited:false};delete labRun.ink;labData().runs[selectedCourseId]=labRun;navigate('labplay');return true}
const labRecallProofs=new WeakMap();
function labPinyinKey(value){return String(value||'').toLowerCase().normalize('NFD').replace(/u:|u\u0308/g,'v').replace(/[\u0300-\u036f]/g,'').replace(/[1-5\s'’·-]/g,'')}
function labSubmitRecall(value,id=labRun?.id,pos=labRun?.pos){const r=labRun,q=labCurrent();if(currentView!=='labplay'||!r||r.id!==id||r.pos!==pos||r.feedback||q?.kind!=='recall')return false;const answer=labPinyinKey(value);if(!answer)return toast('Type the reading first.');const correct=labPinyinOptions(q.pinyin).includes(answer);if(correct){let proofs=labRecallProofs.get(r);if(!proofs){proofs=new Set();labRecallProofs.set(r,proofs)}proofs.add(pos)}return labResolve(correct)}
function labRecallKey(event,id,pos){if(event.key==='Enter'&&!event.isComposing&&!event.repeat){event.preventDefault();event.stopPropagation();labSubmitRecall(event.target.value,id,pos)}}

function labPinyinOptions(value){return [...new Set(String(value||'').split(/[\/;|,]/).map(labPinyinKey).filter(x=>/^[a-zv]+$/.test(x)))]}
function labCanRecall(value){return labPinyinOptions(value).length>0}
